  "admin.compliance.surface.roadmapPre": "อ่านแผนงานเลเยอร์ข้อมูลฉบับเต็มได้ที่",
  "admin.compliance.surface.roadmapPost": "สำหรับทุกสิ่งที่กำลังดำเนินการอยู่",
  "admin.compliance.questionsIntro": "คำถามที่แบบสอบถามด้านความปลอดภัยมักไม่ครอบคลุมถึง — ยินดีตอบเป็นลายลักษณ์อักษร:",
  "admin.compliance.q.subprocessors": "ผู้ประมวลผลย่อยที่ระบุ (โครงสร้างพื้นฐานของ Avalant ในประเทศไทยสำหรับโฮสติ้ง, ผู้ให้บริการ LLM ที่คุณเลือก, Stripe สำหรับการเรียกเก็บเงิน)",
  "admin.compliance.q.incidentResponse": "แผนรับมือเหตุการณ์ + กรอบเวลาการแจ้งเตือนการรั่วไหลของข้อมูล",
