  "releaseLog.roadmapLink.clean": "ทุกรายการใน Roadmap ที่ระบุว่า \"เสร็จแล้ว\" มีสัญญาณในโค้ดรองรับจริง — ดูรายงาน ดาวน์โหลดเป็น PDF ได้",
